package main

import (
	"sync"
	"time"

	"github.com/robertkrimen/otto"
)

// FilterItems filters a slice of map[string]interface{} items using a JavaScript condition script.
// The script is evaluated once per item, with the current item exposed as the global variable 'item'.
// The script should evaluate to a truthy or falsy value; items for which the script is truthy are included in the result.
//
// Security measures implemented:
// - Per-item VM creation to prevent cross-item contamination
// - Script execution timeout to prevent infinite loops
// - Input sanitization to prevent prototype pollution
// - Resource cleanup via defer
func FilterItems(conditionScript string, items []map[string]interface{}) ([]map[string]interface{}, error) {
	var result []map[string]interface{}

	for _, item := range items {
		vm := otto.New()

		// Set execution timeout to prevent denial of service
		// Use a goroutine to enforce timeout since otto doesn't have SetTimeout
		done := make(chan struct{})
		var value otto.Value
		var runErr error

		go func() {
			// Sanitize item keys to prevent prototype pollution
			sanitizedItem := sanitizeMap(item)

			// Inject the current item as a global variable named 'item'
			err := vm.Set("item", sanitizedItem)
			if err != nil {
				runErr = err
				close(done)
				return
			}

			// Run the condition script
			val, err := vm.Run(conditionScript)
			if err != nil {
				runErr = err
				close(done)
				return
			}
			value = val
			close(done)
		}()

		// Wait for completion or timeout
		select {
		case <-done:
			if runErr != nil {
				vm = nil
				return nil, runErr
			}
		case <-time.After(100 * time.Millisecond):
			vm = nil
			return nil, &TimeoutError{Message: "script execution timed out"}
		}

		// Convert result to boolean using JavaScript truthiness
		boolResult, err := value.ToBoolean()
		if err != nil {
			vm = nil
			return nil, err
		}

		if boolResult {
			result = append(result, item)
		}

		// Clean up VM resources
		vm = nil
	}

	return result, nil
}

// TimeoutError represents a script execution timeout error
type TimeoutError struct {
	Message string
}

func (e *TimeoutError) Error() string {
	return e.Message
}

// sanitizeMap recursively sanitizes map keys to prevent JavaScript prototype pollution
func sanitizeMap(input map[string]interface{}) map[string]interface{} {
	output := make(map[string]interface{}, len(input))

	for key, value := range input {
		// Skip dangerous keys that could be used for prototype pollution
		if key == "__proto__" || key == "constructor" || key == "prototype" {
			continue
		}

		// Recursively sanitize nested maps
		if nestedMap, ok := value.(map[string]interface{}); ok {
			output[key] = sanitizeMap(nestedMap)
		} else {
			output[key] = value
		}
	}

	return output
}

