// Helper function to convert map[string]interface{} values to JavaScript-compatible types
func convertToJSValue(v interface{}) interface{} {
	val := reflect.ValueOf(v)
	switch val.Kind() {
	case reflect.Map:
		m := make(map[string]interface{})
		for _, key := range val.MapKeys() {
			m[fmt.Sprint(key.Interface())] = convertToJSValue(val.MapIndex(key).Interface())
		}
		return m
	case reflect.Slice:
		s := make([]interface{}, val.Len())
		for i := 0; i < val.Len(); i++ {
			s[i] = convertToJSValue(val.Index(i).Interface())
		}
		return s
	default:
		return v
	}
}

