package main

import (
	"fmt"
	"log"

	"github.com/robertkrimen/otto"
)

// FilterItems filters a slice of maps using a JavaScript condition script.
// The script is executed for each item, with the item available as the global variable "item".
// Items for which the script evaluates to true are included in the result.
func FilterItems(conditionScript string, items []map[string]interface{}) ([]map[string]interface{}, error) {
	vm := otto.New()
	var result []map[string]interface{}

	for _, item := range items {
		// Inject the current item into the VM as the global variable "item"
		if err := vm.Set("item", item); err != nil {
			return nil, fmt.Errorf("failed to set item in VM: %w", err)
		}

		// Execute the condition script
		value, err := vm.Run(conditionScript)
		if err != nil {
			return nil, fmt.Errorf("failed to execute script for item %v: %w", item, err)
		}

		// Convert the result to a boolean
		booleanValue, err := value.ToBoolean()
		if err != nil {
			return nil, fmt.Errorf("failed to convert script result to boolean for item %v: %w", item, err)
		}

		if booleanValue {
			result = append(result, item)
		}
	}

	return result, nil
}

func main() {
	// Example usage
	items := []map[string]interface{}{
		{"name": "Alice", "age": 30},
		{"name": "Bob", "age": 25},
		{"name": "Charlie", "age": 35},
	}

	script := "item.age >= 30"

	filtered, err := FilterItems(script, items)
	if err != nil {
		log.Fatalf("Error filtering items: %v", err)
	}

	fmt.Println("Filtered items:")
	for _, item := range filtered {
		fmt.Printf("  %v\n", item)
	}
}

